package com.vignesh.banking.model;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.LocalDateTime;
@Entity @Table(name="transactions")
public class Transaction{ @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String fromAccount; private String toAccount; private BigDecimal amount; private String type; private LocalDateTime createdAt=LocalDateTime.now(); @ManyToOne @JoinColumn(name="account_id") private Account account; public Long getId(){return id;} public void setId(Long i){id=i;} public String getFromAccount(){return fromAccount;} public void setFromAccount(String s){fromAccount=s;} public String getToAccount(){return toAccount;} public void setToAccount(String s){toAccount=s;} public BigDecimal getAmount(){return amount;} public void setAmount(BigDecimal a){amount=a;} public String getType(){return type;} public void setType(String t){type=t;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime t){createdAt=t;} public Account getAccount(){return account;} public void setAccount(Account a){account=a;} }
